"""Scam and cyber-fraud methods (data only) for scams_db.py. Each entry: key: (aliases, en, fr, rw, sw); each language is (name, what it is, example, how to protect yourself).
Descriptions are general and protective (how to recognise and resist), not instructions for committing fraud. Examples are invented illustrations, not real messages or real organisations.
fr/rw/sw wording is a draft for fluent review."""

DATA = {
"phishing": (["phishing", "fake email", "fake emails"],
  ("Phishing", "A fake message (usually email) that pretends to come from a trusted organisation to make you click a link, open a file or enter a password.", "An email says “Your account will close in 24 hours, log in here” and the link opens a copy of the real login page.", "Never log in through links in messages; type the address yourself or use the official app, and check the sender and the web address."),
  ("Hameçonnage (phishing)", "Un faux message (souvent un e-mail) prétendant venir d'une organisation de confiance pour vous faire cliquer sur un lien, ouvrir un fichier ou saisir un mot de passe.", "Un e-mail dit « Votre compte sera fermé dans 24 h, connectez-vous ici » et le lien ouvre une copie de la vraie page de connexion.", "Ne vous connectez jamais via les liens d'un message ; saisissez vous-même l'adresse ou utilisez l'application officielle, et vérifiez l'expéditeur et l'adresse web."),
  ("Phishing (ubutumwa bw'uburiganya)", "Ni ubutumwa bw'uburiganya (akenshi imeri) bwigira ubw'ikigo wizeye kugira ngo ukande kuri link, ufungure dosiye cyangwa utange ijambo ry'ibanga.", "Imeri ivuga ngo «Konti yawe izafungwa mu masaha 24, injira hano» kandi link ifungura kopi y'urupapuro nyarwo rwo kwinjiraho.", "Ntukinjire ukoresheje link zo mu butumwa; andika aderesi wowe ubwawe cyangwa ukoreshe porogaramu y'ukuri, ukore igenzura ry'uwohereje n'aderesi y'urubuga."),
  ("Hadaa za mtandaoni (phishing)", "Ujumbe bandia (mara nyingi barua pepe) unaojifanya kutoka shirika la kuaminika ili ubonyeze kiungo, ufungue faili au uweke nenosiri.", "Barua pepe inasema «Akaunti yako itafungwa baada ya saa 24, ingia hapa» na kiungo kinafungua nakala ya ukurasa halisi wa kuingia.", "Usiingie kupitia viungo vya ujumbe; andika anwani mwenyewe au tumia programu rasmi, na uhakiki mtumaji na anwani ya wavuti.")),
"spearphishing": (["spear phishing", "spearphishing", "targeted phishing"],
  ("Spear phishing", "A phishing message written for one person or company, using real details (name, job, colleagues) so that it looks believable.", "An email to an accountant mentions the real manager's name and asks to open an “updated supplier list”.", "Verify unusual requests through another channel (call the person), and be careful with attachments even from known names."),
  ("Spear phishing (hameçonnage ciblé)", "Un message de phishing rédigé pour une personne ou une entreprise précise, avec de vrais détails (nom, poste, collègues) pour paraître crédible.", "Un e-mail à un comptable cite le vrai nom du directeur et demande d'ouvrir une « liste de fournisseurs mise à jour ».", "Vérifiez les demandes inhabituelles par un autre canal (appelez la personne) et méfiez-vous des pièces jointes, même de noms connus."),
  ("Spear phishing (kuroba umuntu umwe)", "Ni phishing yandikiwe umuntu cyangwa ikigo kimwe ikoresheje amakuru nyayo (izina, umwanya, abakozi mukorana) ngo yizerwe.", "Imeri yoherejwe umucungamari ivuga izina nyaryo ry'umuyobozi ikamusaba gufungura «urutonde rushya rw'abatanga ibicuruzwa».", "Emeza ibisabwa bidasanzwe ukoresheje indi nzira (hamagara uwo muntu), kandi wirinde dosiye ziherekeje n'iyo zaturuka ku bazwi."),
  ("Spear phishing (hadaa inayolenga mtu mmoja)", "Ujumbe wa hadaa ulioandikwa kwa mtu au kampuni moja, ukitumia maelezo halisi (jina, kazi, wafanyakazi wenza) ili uaminike.", "Barua pepe kwa mhasibu inataja jina halisi la meneja na kuomba kufungua «orodha mpya ya wasambazaji».", "Thibitisha maombi yasiyo ya kawaida kupitia njia nyingine (mpigie mtu simu), na uwe makini na viambatisho hata vya majina unayoyajua.")),
"whaling": (["whaling", "ceo fraud"],
  ("Whaling (CEO fraud)", "A spear-phishing attack aimed at senior people, or pretending to be a senior person, to get large payments or secret data.", "A message that looks like it is from the director tells the finance officer to pay an urgent invoice today and keep it quiet.", "Use a second approval for payments and always confirm urgent payment requests by phone using a number you already know."),
  ("Whaling (fraude au président)", "Une attaque de phishing ciblé visant des dirigeants, ou se faisant passer pour un dirigeant, afin d'obtenir de gros paiements ou des données secrètes.", "Un message censé venir du directeur ordonne au financier de payer une facture urgente aujourd'hui et de rester discret.", "Exigez une seconde validation des paiements et confirmez toujours une demande de paiement urgente par téléphone, avec un numéro que vous connaissez déjà."),
  ("Whaling (uburiganya bwiyitirira umuyobozi mukuru)", "Ni igitero cya phishing kigenewe abayobozi bakuru, cyangwa cyiyitirira umuyobozi mukuru, kugira ngo babone amafaranga menshi cyangwa amakuru y'ibanga.", "Ubutumwa busa n'ubuvuye ku muyobozi bubwira ushinzwe imari kwishyura fagitire byihutirwa uyu munsi kandi bikaba ibanga.", "Shyiraho kwemeza kwa kabiri ku bwishyu kandi wemeze buri gihe ubwishyu bwihutirwa ukoresheje telefoni kuri nimero usanzwe uzi."),
  ("Whaling (ulaghai wa kujifanya mkurugenzi)", "Shambulio la hadaa linalenga viongozi wakuu, au linalojifanya kiongozi mkuu, ili kupata malipo makubwa au data za siri.", "Ujumbe unaoonekana kutoka kwa mkurugenzi unamwambia afisa wa fedha alipe ankara ya dharura leo na kuiweka siri.", "Weka idhini ya pili kwa malipo na uthibitishe kila ombi la malipo ya dharura kwa simu kwa namba unayoijua tayari.")),
"smishing": (["smishing", "sms phishing", "fake sms", "fake text message", "fake text messages"],
  ("Smishing (SMS phishing)", "Phishing sent by text message (SMS or chat app) with a link or a number to call.", "An SMS says “Your parcel is held, pay a small fee here” with a short link.", "Do not tap links in unexpected texts; contact the company using the number on its official website."),
  ("Smishing (phishing par SMS)", "Phishing envoyé par SMS ou application de messagerie, avec un lien ou un numéro à appeler.", "Un SMS dit « Votre colis est bloqué, payez de petits frais ici » avec un lien raccourci.", "Ne touchez pas les liens des SMS inattendus ; contactez l'entreprise avec le numéro de son site officiel."),
  ("Smishing (phishing ya SMS)", "Phishing yoherezwa muri SMS cyangwa porogaramu y'ubutumwa, irimo link cyangwa nimero yo guhamagara.", "SMS ivuga ngo «Igicuruzwa cyawe cyafashwe, ishyura amafaranga make hano» ifite link ngufi.", "Ntukande kuri link zo mu SMS utari witeze; hamagara ikigo ukoresheje nimero iri ku rubuga rwacyo rw'ukuri."),
  ("Smishing (hadaa ya SMS)", "Hadaa inayotumwa kwa ujumbe mfupi (SMS) au programu ya mazungumzo, ikiwa na kiungo au namba ya kupiga.", "SMS inasema «Kifurushi chako kimezuiliwa, lipa ada ndogo hapa» ikiwa na kiungo kifupi.", "Usibonyeze viungo vya SMS usizotarajia; wasiliana na kampuni kwa namba iliyo kwenye tovuti yake rasmi.")),
"vishing": (["vishing", "voice phishing", "phone scam", "phone call scam", "scam call", "scam calls"],
  ("Vishing (voice phishing)", "A phone call from someone pretending to be a bank, telecom, police or support agent to get PINs, codes or money.", "A caller says “This is your bank, we found fraud, read me the code we just sent you”.", "Hang up and call the organisation yourself. No real bank or mobile-money company asks for your PIN or one-time code."),
  ("Vishing (phishing vocal)", "Un appel téléphonique d'une personne se faisant passer pour une banque, un opérateur, la police ou un support afin d'obtenir des codes PIN ou de l'argent.", "Un appelant dit « Ici votre banque, nous avons détecté une fraude, lisez-moi le code que nous venons de vous envoyer ».", "Raccrochez et rappelez vous-même l'organisme. Aucune vraie banque ni société de mobile money ne demande votre PIN ou code à usage unique."),
  ("Vishing (phishing yo kuri telefoni)", "Ni guhamagarwa n'umuntu wiyitirira banki, ikigo cy'itumanaho, polisi cyangwa ubufasha ngo akubone PIN, kode cyangwa amafaranga.", "Uhamagaye avuga ati «Ni banki yawe, twabonye uburiganya, mbwira kode tukwoherereje».", "Hagarika hanyuma uhamagare ikigo ubwawe. Nta banki cyangwa ikigo cya mobile money nyakuri gisaba PIN cyangwa kode y'rimwe."),
  ("Vishing (hadaa ya simu)", "Simu kutoka kwa mtu anayejifanya benki, kampuni ya simu, polisi au huduma kwa wateja ili kupata PIN, misimbo au pesa.", "Mpigaji anasema «Hii ni benki yako, tumegundua ulaghai, nisomee msimbo tuliokutumia».", "Kata simu kisha mpigie shirika mwenyewe. Hakuna benki au kampuni halisi ya pesa za simu inayoomba PIN au msimbo wa mara moja.")),
"quishing": (["quishing", "qr code scam", "qr scam", "fake qr code", "fake qr codes"],
  ("Quishing (QR-code scam)", "A malicious QR code, on a poster, sticker or message, that opens a fake site or starts a payment when scanned.", "A sticker is placed over a shop's payment QR code so customers pay the wrong person.", "Check the web address shown after scanning, never enter passwords after scanning, and look for stickers placed over real codes."),
  ("Quishing (arnaque au code QR)", "Un code QR malveillant, sur une affiche, un autocollant ou un message, qui ouvre un faux site ou lance un paiement quand on le scanne.", "Un autocollant est collé sur le QR de paiement d'une boutique pour que les clients paient la mauvaise personne.", "Vérifiez l'adresse affichée après le scan, ne saisissez jamais de mot de passe après un scan et repérez les autocollants posés sur les vrais codes."),
  ("Quishing (uburiganya bukoresha QR code)", "Ni QR code mbi, ku cyapa, sitikeri cyangwa mu butumwa, ifungura urubuga rw'uburiganya cyangwa itangira kwishyura iyo uyisikanye.", "Sitikeri ishyirwa hejuru ya QR yo kwishyura y'iduka kugira ngo abakiriya bishyure undi muntu.", "Reba aderesi igaragara nyuma yo gusikana, ntuzigere wandika ijambo ry'ibanga nyuma yo gusikana, kandi urebe sitikeri zashyizwe hejuru ya kode nyayo."),
  ("Quishing (ulaghai wa msimbo wa QR)", "Msimbo wa QR hasidi, kwenye bango, kibandiko au ujumbe, unaofungua tovuti bandia au kuanzisha malipo ukiuskani.", "Kibandiko kimebandikwa juu ya QR ya malipo ya duka ili wateja walipe mtu mwingine.", "Angalia anwani inayoonekana baada ya kuskani, usiweke nenosiri baada ya kuskani, na tazama vibandiko vilivyowekwa juu ya misimbo halisi.")),
"bec": (["business email compromise", "bec", "fake supplier invoice", "payment diversion"],
  ("Business email compromise (BEC)", "Criminals take over or copy a business email account and trick staff or customers into sending money to a changed bank or mobile-money account.", "A supplier's email “changes its bank details” just before a large payment is due.", "Confirm any change of payment details by phone with a known number, and use two-person approval for large payments."),
  ("Compromission de messagerie d'entreprise (BEC)", "Des criminels prennent le contrôle ou copient une messagerie d'entreprise et poussent employés ou clients à envoyer de l'argent vers un compte bancaire ou mobile money modifié.", "L'e-mail d'un fournisseur « change ses coordonnées bancaires » juste avant un gros paiement.", "Confirmez tout changement de coordonnées de paiement par téléphone avec un numéro connu, et exigez une double validation pour les gros paiements."),
  ("Business email compromise (BEC)", "Abagizi ba nabi bafata cyangwa bigana imeri y'ikigo bakayobya abakozi cyangwa abakiriya kohereza amafaranga kuri konti ya banki cyangwa mobile money yahinduwe.", "Imeri y'utanga ibicuruzwa «ihindura konti ya banki» mbere y'uko hishyurwa menshi.", "Emeza impinduka zose z'aho wishyura ukoresheje telefoni kuri nimero izwi, kandi ushyireho abantu babiri bemeza ubwishyu bunini."),
  ("Udukuzi wa barua pepe za biashara (BEC)", "Wahalifu huchukua au kunakili barua pepe ya biashara na kuwadanganya wafanyakazi au wateja kutuma pesa kwa akaunti ya benki au pesa za simu iliyobadilishwa.", "Barua pepe ya msambazaji «inabadilisha taarifa za benki» kabla ya malipo makubwa.", "Thibitisha mabadiliko yoyote ya malipo kwa simu kwa namba inayojulikana, na tumia idhini ya watu wawili kwa malipo makubwa.")),
"mobilemoney": (["mobile money scam", "mobile money fraud", "momo scam", "momo fraud", "wrong transfer scam", "wrong number transfer", "airtel money scam"],
  ("Mobile-money fraud", "Tricks that make you send money or reveal your PIN: fake “wrong transfer” requests, fake agents, fake confirmation messages, and callers claiming your wallet is blocked.", "Someone sends money “by mistake”, then calls begging you to send it back, but the first message was fake or the money is later reversed.", "Check your balance in the official app or with the official code before sending anything back, never share your PIN, and use only registered agents."),
  ("Fraude au mobile money", "Astuces pour vous faire envoyer de l'argent ou révéler votre PIN : fausses demandes de « transfert par erreur », faux agents, faux messages de confirmation, appels disant que votre portefeuille est bloqué.", "Quelqu'un envoie de l'argent « par erreur » puis supplie de le renvoyer, mais le premier message était faux ou l'argent est annulé ensuite.", "Vérifiez votre solde dans l'application ou avec le code officiel avant de renvoyer quoi que ce soit, ne partagez jamais votre PIN et utilisez uniquement des agents enregistrés."),
  ("Uburiganya bwa mobile money", "Amayeri atuma wohereza amafaranga cyangwa utanga PIN: gusaba «gusubiza amafaranga yoherejwe kubera ikosa», abakozi b'impimbano, ubutumwa bw'impimbano bwemeza, n'abahamagara bavuga ko konti yawe ifunze.", "Umuntu yohereza amafaranga «kubera ikosa» agahamagara agusaba kuyasubiza, ariko ubutumwa bwa mbere bwari ibinyoma cyangwa amafaranga arakurwaho nyuma.", "Reba amafaranga ufite muri porogaramu y'ukuri cyangwa kode y'ukuri mbere yo gusubiza, ntugatange PIN, kandi ukoreshe gusa abakozi biyandikishije."),
  ("Ulaghai wa pesa za simu", "Mbinu za kukufanya utume pesa au utoe PIN: maombi bandia ya «kurudisha pesa zilizotumwa kimakosa», mawakala bandia, jumbe bandia za uthibitisho, na wapigaji wanaosema pochi yako imezuiwa.", "Mtu anatuma pesa «kimakosa» kisha anakuomba sana urudishe, lakini ujumbe wa kwanza ulikuwa bandia au pesa zinarudishwa baadaye.", "Angalia salio kwenye programu rasmi au kwa msimbo rasmi kabla ya kurudisha chochote, usishiriki PIN, na tumia mawakala waliosajiliwa tu.")),
"simswap": (["sim swap", "sim swapping", "sim swap fraud", "sim card swap"],
  ("SIM swap", "A criminal convinces a mobile operator (or a dishonest insider) to move your number to a new SIM, then receives your calls, texts and one-time codes.", "Your phone suddenly loses signal while your accounts start sending password-reset codes you did not ask for.", "Add a PIN to your SIM/account where possible, tell your operator at once if you lose signal unexpectedly, and use app-based codes instead of SMS where offered."),
  ("Échange de SIM (SIM swap)", "Un criminel convainc un opérateur (ou un employé malhonnête) de transférer votre numéro vers une nouvelle SIM, puis reçoit vos appels, SMS et codes à usage unique.", "Votre téléphone perd soudain le réseau pendant que vos comptes envoient des codes de réinitialisation que vous n'avez pas demandés.", "Ajoutez un code à votre SIM/compte si possible, prévenez aussitôt l'opérateur si le réseau disparaît sans raison, et préférez les codes d'application aux SMS quand c'est proposé."),
  ("SIM swap (guhindura SIM)", "Umuhemu yemeza ikigo cy'itumanaho (cyangwa umukozi utizewe) kwimura nimero yawe kuri SIM nshya, hanyuma agahabwa guhamagara, SMS na kode zawe.", "Telefoni yawe ihita ibura network mu gihe konti zawe zitangiye kohereza kode zo guhindura ijambo ry'ibanga utasabye.", "Shyiraho PIN kuri SIM/konti aho bishoboka, menyesha ikigo vuba iyo network ibuze utabyiteze, kandi ukoreshe kode zo muri porogaramu aho zihari aho gukoresha SMS."),
  ("Kubadilisha SIM (SIM swap)", "Mhalifu anaishawishi kampuni ya simu (au mfanyakazi asiye mwaminifu) kuhamishia namba yako kwenye SIM mpya, kisha anapokea simu, SMS na misimbo yako ya mara moja.", "Simu yako inapoteza mtandao ghafla huku akaunti zako zikituma misimbo ya kubadilisha nenosiri ambayo hukuiomba.", "Weka PIN kwenye SIM/akaunti inapowezekana, mwambie mtoa huduma mara moja mtandao ukipotea ghafla, na tumia misimbo ya programu badala ya SMS inapopatikana.")),
"techsupport": (["tech support scam", "fake tech support", "fake support", "remote access scam", "fake antivirus"],
  ("Fake tech-support scam", "A pop-up, call or message says your device is infected and urges you to call a number or install remote-control software, then charges you or steals data.", "A full-screen warning with a loud alarm says “Virus found, call this number now”.", "Close the page, never install remote-access tools for strangers, and ask a trusted technician. Real warnings do not give a phone number to call."),
  ("Arnaque au faux support technique", "Une fenêtre, un appel ou un message dit que votre appareil est infecté et vous pousse à appeler un numéro ou installer un logiciel de contrôle à distance, puis vous fait payer ou vole des données.", "Un avertissement plein écran avec alarme dit « Virus détecté, appelez ce numéro maintenant ».", "Fermez la page, n'installez jamais d'outil d'accès à distance pour un inconnu et demandez à un technicien de confiance. De vrais avertissements ne donnent pas de numéro à appeler."),
  ("Uburiganya bw'ubufasha bwa tekiniki bw'impimbano", "Ubutumwa, guhamagara cyangwa idirishya rivuga ko igikoresho cyawe cyanduye kandi rigusaba guhamagara nimero cyangwa gushyiraho porogaramu yo kugenzura kure, hanyuma bakakwaka amafaranga cyangwa bakiba amakuru.", "Impuruza yuzuye ecran ifite ijwi ivuga iti «Virusi yabonetse, hamagara iyi nimero ubu».", "Funga urupapuro, ntuzigere ushyiraho porogaramu zo kugenzura kure ku batazwi, ubaze umutekinisiye wizeye. Impuruza nyakuri ntizitanga nimero yo guhamagara."),
  ("Ulaghai wa msaada wa kiufundi bandia", "Dirisha, simu au ujumbe unasema kifaa chako kimeambukizwa na kukushinikiza upige namba au usakinishe programu ya udhibiti wa mbali, kisha wanakutoza au kuiba data.", "Onyo la skrini nzima lenye kengele kubwa linasema «Virusi imepatikana, piga namba hii sasa».", "Funga ukurasa, usisakinishe zana za mbali kwa wageni, na muulize fundi unayemwamini. Maonyo halisi hayatoi namba ya kupiga.")),
"romance": (["romance scam", "dating scam", "love scam", "catfishing", "catfish"],
  ("Romance scam", "A criminal builds a fake online relationship, often with stolen photos, then invents emergencies to ask for money, gifts or investments.", "A “partner” you have never met says they are stuck at an airport and need money for a ticket.", "Never send money to someone you have not met in person, be careful when the person avoids video calls, and do a reverse image search on their photos."),
  ("Arnaque sentimentale", "Un criminel construit une fausse relation en ligne, souvent avec des photos volées, puis invente des urgences pour demander de l'argent, des cadeaux ou des investissements.", "Un « partenaire » que vous n'avez jamais rencontré dit être bloqué dans un aéroport et avoir besoin d'argent pour un billet.", "N'envoyez jamais d'argent à quelqu'un que vous n'avez pas rencontré, méfiez-vous s'il évite les appels vidéo et faites une recherche d'image inversée de ses photos."),
  ("Uburiganya bw'urukundo", "Umuhemu yubaka umubano w'impimbano kuri interineti, akenshi akoresheje amafoto yibwe, hanyuma agahimba ibibazo byihutirwa asaba amafaranga, impano cyangwa ishoramari.", "«Uwo mukundana» utarigeze ubona avuga ko yafatiwe ku kibuga cy'indege akeneye amafaranga y'itike.", "Ntuzigere wohereza amafaranga ku muntu utarabona imbonankubone, wirinde iyo yanga guhamagara kuri video, kandi ushakishe amafoto ye ukoresheje gushakisha ishusho."),
  ("Ulaghai wa mapenzi", "Mhalifu hujenga uhusiano bandia mtandaoni, mara nyingi kwa picha zilizoibwa, kisha huunda dharura ili kuomba pesa, zawadi au uwekezaji.", "«Mpenzi» ambaye hujawahi kukutana naye anasema amekwama uwanja wa ndege na anahitaji pesa za tiketi.", "Usitume pesa kwa mtu ambaye hujakutana naye ana kwa ana, uwe makini akikwepa simu za video, na tafuta picha zake kwa utafutaji wa picha.")),
"advancefee": (["advance fee", "advance-fee", "419 scam", "inheritance scam", "nigerian prince", "fee to release funds"],
  ("Advance-fee scam", "You are promised a large sum, inheritance, contract or loan, but must first pay “fees”, taxes or “clearance”. The big payment never comes.", "A message says a distant relative left you a large inheritance, but you must pay a release fee first.", "Real winnings, loans and inheritances never require you to pay a stranger first. Do not pay, and do not share ID documents."),
  ("Arnaque aux frais d'avance", "On vous promet une grosse somme, un héritage, un contrat ou un prêt, mais vous devez d'abord payer des « frais », taxes ou « dédouanement ». La grosse somme ne vient jamais.", "Un message dit qu'un lointain parent vous a laissé un gros héritage, mais vous devez d'abord payer des frais de libération.", "De vrais gains, prêts ou héritages n'exigent jamais de payer d'abord un inconnu. Ne payez pas et ne partagez pas vos pièces d'identité."),
  ("Uburiganya bwo kwishyura mbere", "Barakwizeza amafaranga menshi, umurage, isoko cyangwa inguzanyo, ariko ugomba kubanza kwishyura «amafaranga», imisoro cyangwa «kurekura». Amafaranga manini ntabonekaho.", "Ubutumwa buvuga ko mwene wanyu wo kure yagusigiye umurage munini, ariko ugomba kubanza kwishyura amafaranga yo kuwurekura.", "Ibyo watsindiye, inguzanyo cyangwa umurage nyakuri ntibisaba kubanza kwishyura umuntu utazi. Ntukishyure kandi ntugasangize indangamuntu."),
  ("Ulaghai wa ada ya awali", "Unaahidiwa kiasi kikubwa, urithi, kandarasi au mkopo, lakini lazima ulipe kwanza «ada», kodi au «kibali». Malipo makubwa hayaji kamwe.", "Ujumbe unasema ndugu wa mbali amekuachia urithi mkubwa, lakini lazima ulipe ada ya kuachilia kwanza.", "Ushindi, mikopo na urithi halisi havikuhitaji ulipe mgeni kwanza. Usilipe na usishiriki vitambulisho.")),
"lottery": (["lottery scam", "prize scam", "you won", "fake prize", "fake lottery", "winner scam", "sweepstake scam"],
  ("Lottery and prize scam", "A message says you won a lottery, phone, car or cash prize you never entered, then asks for a fee, personal details or your PIN to “release” it.", "“Congratulations, you won 5,000,000! Send a small fee to claim it.”", "You cannot win a contest you did not enter. Do not pay or share details; delete the message and block the sender."),
  ("Arnaque à la loterie et aux prix", "Un message dit que vous avez gagné une loterie, un téléphone, une voiture ou de l'argent sans avoir participé, puis demande des frais, des données personnelles ou votre PIN pour « débloquer » le gain.", "« Félicitations, vous avez gagné 5 000 000 ! Envoyez de petits frais pour le recevoir. »", "On ne peut pas gagner un concours auquel on n'a pas participé. Ne payez pas, ne partagez rien ; supprimez le message et bloquez l'expéditeur."),
  ("Uburiganya bw'tombola n'ibihembo", "Ubutumwa buvuga ko watsindiye tombola, telefoni, imodoka cyangwa amafaranga utigeze witabira, hanyuma bugasaba amafaranga, amakuru bwite cyangwa PIN ngo «barekure» igihembo.", "«Turabashimiye, mwatsindiye 5,000,000! Ohereza amafaranga make ugire ngo uyakire.»", "Ntushobora gutsinda irushanwa utitabiriye. Ntukishyure kandi ntugatange amakuru; siba ubutumwa ubuze uwabwohereje."),
  ("Ulaghai wa bahati nasibu na zawadi", "Ujumbe unasema umeshinda bahati nasibu, simu, gari au pesa ambazo hukuingia, kisha unaomba ada, taarifa binafsi au PIN ili «kuachilia» zawadi.", "«Hongera, umeshinda 5,000,000! Tuma ada ndogo ili uipokee.»", "Huwezi kushinda shindano ambalo hukuingia. Usilipe wala kutoa taarifa; futa ujumbe na umzuie mtumaji.")),
"fakejob": (["fake job", "fake job offer", "job scam", "employment scam", "recruitment scam", "fake recruiter"],
  ("Fake job offer", "A too-good job offer asks you to pay for training, a uniform, a visa or “registration”, or to hand over ID and bank details, or to move money for the employer.", "A recruiter on chat offers a high salary with no interview, but you must first pay a registration fee.", "Real employers do not charge applicants. Check the company independently, meet or call through official channels, and never share ID or banking details early."),
  ("Fausse offre d'emploi", "Une offre d'emploi trop belle demande de payer une formation, un uniforme, un visa ou une « inscription », ou de remettre pièce d'identité et coordonnées bancaires, ou de transférer de l'argent pour l'employeur.", "Un recruteur sur messagerie propose un gros salaire sans entretien, mais il faut d'abord payer des frais d'inscription.", "Les vrais employeurs ne font pas payer les candidats. Vérifiez l'entreprise de façon indépendante, passez par les canaux officiels et ne donnez jamais pièce d'identité ou données bancaires tôt."),
  ("Itangazo ry'akazi ry'impimbano", "Itangazo ry'akazi ryiza birenze rigusaba kwishyura amahugurwa, impuzankano, viza cyangwa «kwiyandikisha», gutanga indangamuntu n'amakuru ya banki, cyangwa kwimura amafaranga ku mukoresha.", "Ushaka abakozi kuri chat atanga umushahara munini nta kwiyerekana, ariko ugomba kubanza kwishyura amafaranga yo kwiyandikisha.", "Abakoresha nyakuri ntibishyuza abasaba akazi. Genzura ikigo mu buryo bwigenga, banza inzira zemewe, kandi ntugatange indangamuntu cyangwa amakuru ya banki kare."),
  ("Ofa ya kazi bandia", "Ofa ya kazi nzuri kupita kiasi inakuomba ulipe mafunzo, sare, visa au «usajili», au utoe kitambulisho na taarifa za benki, au uhamishe pesa kwa mwajiri.", "Mwajiri kwenye gumzo anatoa mshahara mkubwa bila usaili, lakini lazima ulipe ada ya usajili kwanza.", "Waajiri halisi hawawatozi waombaji. Hakiki kampuni kwa kujitegemea, tumia njia rasmi, na usitoe kitambulisho au taarifa za benki mapema.")),
"investment": (["investment scam", "crypto scam", "ponzi", "pyramid scheme", "ponzi scheme", "pig butchering", "fake trading platform", "fake investment", "get rich quick"],
  ("Investment, crypto and Ponzi scams", "Promises of high, guaranteed returns through fake trading platforms, crypto schemes or pyramid schemes where early members are paid with new members' money until it collapses.", "A group says “Invest 100,000 and get double in a week”, shows fake profits on a website, then blocks withdrawals.", "Guaranteed high returns are a warning sign. Check that the company is licensed with the national regulator, never invest because of pressure, and be wary of recruiting others."),
  ("Arnaques à l'investissement, aux cryptomonnaies et de type Ponzi", "Promesses de gains élevés et garantis via de fausses plateformes de trading, des combines crypto ou des pyramides où les premiers membres sont payés avec l'argent des nouveaux jusqu'à l'effondrement.", "Un groupe dit « Investissez 100 000 et recevez le double en une semaine », montre de faux profits sur un site, puis bloque les retraits.", "Des gains élevés garantis sont un signal d'alerte. Vérifiez que l'entreprise est agréée auprès du régulateur national, n'investissez jamais sous pression et méfiez-vous du recrutement d'autres personnes."),
  ("Uburiganya bw'ishoramari, crypto na Ponzi", "Amasezerano y'inyungu nyinshi zemewe binyuze ku mbuga z'impimbano z'ubucuruzi, crypto cyangwa za piramide aho abinjiye mbere bishyurwa n'amafaranga y'abashya kugeza byaguye.", "Itsinda rivuga riti «Shora 100,000 ubone abiri mu cyumweru», rikerekana inyungu z'ibinyoma ku rubuga, hanyuma rigahagarika kubikuza.", "Inyungu nyinshi zemewe ni ikimenyetso cy'ububi. Reba ko ikigo gifite uruhushya rw'urwego rubifite, ntushore kubera igitutu, kandi wirinde gushaka abandi."),
  ("Ulaghai wa uwekezaji, crypto na Ponzi", "Ahadi za faida kubwa za uhakika kupitia majukwaa bandia ya biashara, mipango ya crypto au piramidi ambapo wanachama wa kwanza hulipwa kwa pesa za wapya hadi inapoanguka.", "Kikundi kinasema «Wekeza 100,000 upate mara mbili kwa wiki», kinaonyesha faida bandia kwenye tovuti, kisha kinazuia kutoa pesa.", "Faida kubwa za uhakika ni ishara ya hatari. Hakiki kampuni ina leseni ya mdhibiti wa taifa, usiwekeze kwa shinikizo, na jihadhari na kuwaajiri wengine.")),
"fakeshop": (["fake online shop", "fake shop", "fake website", "fake store", "online shopping scam", "fake online store", "fake websites"],
  ("Fake online shop", "A professional-looking website or social-media shop sells popular items at very low prices, takes your payment and never delivers, or steals your card details.", "A page sells new phones at half price, accepts only advance payment and disappears after orders.", "Search the shop's name with “reviews” or “scam”, prefer cash on delivery or protected payment, and be careful with prices far below normal."),
  ("Faux site de vente en ligne", "Un site ou une boutique de réseau social à l'air professionnel vend des articles populaires à très bas prix, encaisse votre paiement sans livrer, ou vole vos données de carte.", "Une page vend des téléphones neufs à moitié prix, n'accepte que le paiement d'avance et disparaît après les commandes.", "Cherchez le nom de la boutique avec « avis » ou « arnaque », préférez le paiement à la livraison ou un paiement protégé, et méfiez-vous des prix très inférieurs à la normale."),
  ("Iduka ryo kuri interineti ry'impimbano", "Urubuga cyangwa iduka ryo ku mbuga nkoranyambaga risa n'iry'umwuga rigurisha ibintu bikunzwe ku giciro gito cyane, rikakira amafaranga ntiritange ibicuruzwa, cyangwa ryiba amakuru ya karita.", "Urupapuro rugurisha telefoni nshya ku giciro cy'ikubitiro, rwemera kwishyura mbere gusa kandi rukazimira nyuma y'ibyategetswe.", "Shakisha izina ry'iduka hamwe na «reviews» cyangwa «scam», hitamo kwishyura wakiriye cyangwa uburyo burinzwe, kandi wirinde ibiciro biri hasi cyane."),
  ("Duka bandia la mtandaoni", "Tovuti au duka la mitandao ya kijamii linaloonekana la kitaalamu linauza bidhaa maarufu kwa bei ndogo sana, linachukua malipo na halitoi bidhaa, au kuiba taarifa za kadi.", "Ukurasa unauza simu mpya kwa nusu bei, unakubali malipo ya awali tu na kutoweka baada ya oda.", "Tafuta jina la duka na «reviews» au «scam», pendelea malipo wakati wa kupokea au malipo yaliyolindwa, na uwe makini na bei ndogo kupita kawaida.")),
"fakecharity": (["fake charity", "charity scam", "donation scam", "fake fundraising", "fake donation"],
  ("Fake charity and donation scam", "Criminals ask for donations for a disaster, a sick child or a charity that does not exist, often copying real stories and photos.", "After a flood, a message asks you to send money to a personal mobile-money number “for victims”.", "Give only through organisations you can verify, and not to a personal number. Be wary of emotional pressure to give at once."),
  ("Fausse association caritative et faux appels aux dons", "Des criminels demandent des dons pour une catastrophe, un enfant malade ou une association inexistante, copiant souvent de vraies histoires et photos.", "Après une inondation, un message demande d'envoyer de l'argent à un numéro mobile money personnel « pour les victimes ».", "Donnez seulement via des organisations vérifiables, pas à un numéro personnel. Méfiez-vous de la pression émotionnelle pour donner tout de suite."),
  ("Uburiganya bw'umuryango utegamiye kuri leta n'impano by'impimbano", "Abagizi ba nabi basaba impano z'ibiza, umwana urwaye cyangwa umuryango udahari, akenshi bakopera inkuru n'amafoto nyakuri.", "Nyuma y'umwuzure, ubutumwa busaba kohereza amafaranga kuri nimero bwite ya mobile money «ku bahuye n'ibiza».", "Tanga gusa binyuze mu miryango ushobora kugenzura, ntukoherezwe kuri nimero bwite. Wirinde igitutu cy'amarangamutima cyo gutanga ako kanya."),
  ("Ulaghai wa mashirika ya hisani na michango", "Wahalifu wanaomba michango kwa maafa, mtoto mgonjwa au shirika lisilokuwepo, mara nyingi wakinakili hadithi na picha halisi.", "Baada ya mafuriko, ujumbe unaomba kutuma pesa kwa namba binafsi ya pesa za simu «kwa waathirika».", "Changia tu kupitia mashirika unayoweza kuyahakiki, si namba binafsi. Jihadhari na shinikizo la hisia la kutoa mara moja.")),
"impersonation": (["impersonation scam", "official impersonation", "bank impersonation", "government impersonation", "fake police", "fake official", "fake bank", "fake bank message", "police scam"],
  ("Impersonation of banks, officials and companies", "Scammers pretend to be a bank, tax office, police, telecom company or government service and use fear (“your account is blocked”, “you owe a fine”) to make you act.", "A caller claims to be from a tax office and says you must pay a penalty immediately by mobile money.", "Officials do not demand immediate payment or secret codes by phone or chat. Hang up and contact the real institution using its official number."),
  ("Usurpation d'identité de banques, d'autorités et d'entreprises", "Des escrocs se font passer pour une banque, le fisc, la police, un opérateur ou un service public et utilisent la peur (« votre compte est bloqué », « vous devez une amende ») pour vous faire agir.", "Un appelant se dit du fisc et affirme qu'il faut payer immédiatement une pénalité par mobile money.", "Les autorités n'exigent pas de paiement immédiat ni de codes secrets par téléphone ou messagerie. Raccrochez et contactez la vraie institution via son numéro officiel."),
  ("Kwiyitirira bank, abayobozi n'ibigo", "Abatekamutwe biyitirira banki, ikigo cy'imisoro, polisi, ikigo cy'itumanaho cyangwa serivisi za leta bakoresha ubwoba («konti yawe ifunze», «ufite ihazabu») ngo ugire icyo ukora.", "Uhamagaye yiyita ikigo cy'imisoro akavuga ko ugomba kwishyura ihazabu ako kanya kuri mobile money.", "Abayobozi ntibasaba kwishyura ako kanya cyangwa kode z'ibanga kuri telefoni cyangwa chat. Hagarika hanyuma uhamagare ikigo nyakuri ukoresheje nimero yacyo y'ukuri."),
  ("Kujifanya benki, maafisa na kampuni", "Matapeli hujifanya benki, mamlaka ya kodi, polisi, kampuni ya simu au huduma ya serikali na kutumia hofu («akaunti yako imezuiwa», «una faini») ili ufanye kitu.", "Mpigaji anajidai kuwa wa mamlaka ya kodi na kusema ulipe adhabu mara moja kwa pesa za simu.", "Maafisa hawadai malipo ya papo hapo au misimbo ya siri kwa simu au gumzo. Kata simu na uwasiliane na taasisi halisi kwa namba yake rasmi.")),
"ransomware": (["ransomware", "ransom attack", "file encryption attack"],
  ("Ransomware", "Malicious software that locks or encrypts your files or systems and demands payment to unlock them. It often arrives through phishing or unpatched software.", "A company opens an infected attachment and every file is renamed with a message demanding payment.", "Keep offline backups, update software, do not open unexpected attachments, and report the incident. Paying does not guarantee recovery."),
  ("Rançongiciel (ransomware)", "Logiciel malveillant qui verrouille ou chiffre vos fichiers ou systèmes et exige un paiement pour les débloquer. Il arrive souvent par phishing ou logiciels non mis à jour.", "Une entreprise ouvre une pièce jointe infectée et tous les fichiers sont renommés avec un message exigeant un paiement.", "Gardez des sauvegardes hors ligne, mettez à jour les logiciels, n'ouvrez pas les pièces jointes inattendues et signalez l'incident. Payer ne garantit pas la récupération."),
  ("Ransomware (porogaramu ifunga dosiye ikaka incungu)", "Porogaramu mbi ifunga cyangwa ihisha dosiye cyangwa sisitemu zawe ikaka amafaranga yo kuzifungura. Akenshi iza binyuze muri phishing cyangwa porogaramu zitavuguruwe.", "Ikigo gifungura dosiye yanduye maze dosiye zose zigahindurirwa amazina haboneka ubutumwa busaba kwishyura.", "Bika kopi zitari kuri interineti, vugurura porogaramu, ntufungure dosiye utiteze, kandi utange raporo. Kwishyura ntibyemeza ko uzazibona."),
  ("Ransomware (programu inayofunga mafaili na kudai fidia)", "Programu hasidi inayofunga au kusimba mafaili au mifumo yako na kudai malipo ili kuyafungua. Mara nyingi huja kupitia hadaa au programu zisizosasishwa.", "Kampuni inafungua kiambatisho kilichoambukizwa na mafaili yote yanabadilishwa majina na ujumbe wa kudai malipo.", "Hifadhi nakala nje ya mtandao, sasisha programu, usifungue viambatisho usivyotarajia, na ripoti tukio. Kulipa hakuhakikishi kurejeshewa.")),
"malware": (["malware", "trojan", "computer virus", "virus attack", "infected file", "cracked software"],
  ("Malware (viruses, trojans, worms)", "Harmful software that hides in downloads, cracked programs, attachments or fake apps to steal data, damage files or take control of a device.", "A “free” cracked game installer also installs a hidden program that steals saved passwords.", "Install software only from official stores or sites, keep devices updated, avoid cracked software, and use a trusted security app."),
  ("Logiciels malveillants (virus, chevaux de Troie, vers)", "Logiciels nuisibles cachés dans des téléchargements, programmes piratés, pièces jointes ou fausses applications pour voler des données, endommager des fichiers ou prendre le contrôle d'un appareil.", "Un installateur de jeu piraté « gratuit » installe aussi un programme caché qui vole les mots de passe enregistrés.", "Installez des logiciels uniquement depuis les boutiques ou sites officiels, mettez à jour vos appareils, évitez les logiciels piratés et utilisez une application de sécurité fiable."),
  ("Malware (virusi, trojan, worm)", "Porogaramu mbi zihishwa mu byo ukuramo, porogaramu zikuruwe mu buryo butemewe, dosiye ziherekeje cyangwa porogaramu z'impimbano kugira ngo ziyibe amakuru, zangize dosiye cyangwa zifate igikoresho.", "Porogaramu y'umukino «y'ubuntu» yacitse ishyiraho n'indi ihishe yiba amajambo y'ibanga abitswe.", "Shyiraho porogaramu gusa mu maduka cyangwa ku mbuga z'ukuri, vugurura ibikoresho, irinde porogaramu zacitse, kandi ukoreshe porogaramu y'umutekano wizeye."),
  ("Programu hasidi (virusi, trojan, worm)", "Programu hatari zinazojificha kwenye vipakuliwa, programu zilizovunjwa, viambatisho au programu bandia ili kuiba data, kuharibu mafaili au kuchukua udhibiti wa kifaa.", "Kisakinishi cha mchezo «bure» kilichovunjwa pia kinasakinisha programu iliyofichwa inayoiba nenosiri zilizohifadhiwa.", "Sakinisha programu kutoka maduka au tovuti rasmi tu, sasisha vifaa, epuka programu zilizovunjwa, na tumia programu ya usalama unayoiamini.")),
"spyware": (["spyware", "stalkerware", "keylogger", "keylogging", "phone spying app"],
  ("Spyware, stalkerware and keyloggers", "Hidden software that secretly records what you type, your messages, location or screen and sends it to someone else.", "A partner or stranger secretly installs a hidden app that forwards messages and location.", "Use a screen lock, check for unknown apps and device-administrator permissions, update your phone, and if you suspect spying get help from a trusted technician."),
  ("Logiciels espions, stalkerware et enregistreurs de frappe", "Logiciels cachés qui enregistrent en secret ce que vous tapez, vos messages, votre position ou votre écran et l'envoient à quelqu'un d'autre.", "Un conjoint ou un inconnu installe en secret une application cachée qui transmet messages et position.", "Utilisez un verrouillage d'écran, cherchez les applications inconnues et les droits d'administrateur de l'appareil, mettez à jour le téléphone et, en cas de doute, demandez l'aide d'un technicien de confiance."),
  ("Spyware, stalkerware na keylogger", "Porogaramu zihishe zandika rwihishwa ibyo wandika, ubutumwa, aho uri cyangwa ecran yawe zikabyohereza ku wundi muntu.", "Uwo mubana cyangwa umuntu utazi ashyiraho rwihishwa porogaramu ihishe yohereza ubutumwa n'aho uri.", "Koresha gufunga ecran, reba porogaramu zitazwi n'uburenganzira bwa «device administrator», vugurura telefoni, kandi niba ukeka ko urebwa ubaze umutekinisiye wizeye."),
  ("Spyware, stalkerware na keylogger", "Programu zilizofichwa zinazorekodi kwa siri unachoandika, ujumbe, mahali ulipo au skrini yako na kuvituma kwa mtu mwingine.", "Mwenzi au mgeni anasakinisha kwa siri programu iliyofichwa inayotuma ujumbe na mahali ulipo.", "Tumia kufunga skrini, angalia programu zisizojulikana na ruhusa za msimamizi wa kifaa, sasisha simu, na ukishuku ufuatiliaji mwombe fundi unayemwamini msaada.")),
"credstuffing": (["credential stuffing", "password reuse attack", "password reuse", "brute force", "brute force attack", "password guessing", "password spraying"],
  ("Credential stuffing and password guessing", "Attackers try passwords leaked from one website on many other sites, or guess common passwords, and get in wherever you reused a password.", "Your password leaked from a small forum is tried on your email and mobile-banking accounts.", "Use a different long password for every important account, a password manager, and two-step verification, especially on email."),
  ("Credential stuffing et devinette de mots de passe", "Des attaquants essaient sur de nombreux sites les mots de passe fuités d'un autre site, ou devinent des mots de passe courants, et entrent partout où vous avez réutilisé un mot de passe.", "Votre mot de passe fuité d'un petit forum est testé sur votre e-mail et vos comptes bancaires mobiles.", "Utilisez un mot de passe long et différent pour chaque compte important, un gestionnaire de mots de passe et la vérification en deux étapes, surtout pour l'e-mail."),
  ("Credential stuffing no kugerageza amajambo y'ibanga", "Abagizi ba nabi bagerageza amajambo y'ibanga yamenetse ku rubuga rumwe ku zindi nyinshi, cyangwa bakeka amajambo asanzwe, bakinjira aho wongeye gukoresha ijambo rimwe.", "Ijambo ryawe ry'ibanga ryamenetse ku rubuga ruto rigeragezwa ku imeri yawe no kuri konti za banki yo kuri telefoni.", "Koresha ijambo ry'ibanga rirerire kandi ritandukanye kuri buri konti y'ingenzi, porogaramu ibika amajambo y'ibanga, na two-step verification, cyane cyane ku imeri."),
  ("Credential stuffing na kubahatisha nenosiri", "Washambuliaji hujaribu nenosiri zilizovuja kutoka tovuti moja kwenye tovuti nyingi, au kubahatisha nenosiri za kawaida, na kuingia popote ulipotumia nenosiri lile lile.", "Nenosiri lako lililovuja kutoka jukwaa dogo linajaribiwa kwenye barua pepe na akaunti zako za benki ya simu.", "Tumia nenosiri refu tofauti kwa kila akaunti muhimu, kidhibiti cha nenosiri, na uthibitishaji wa hatua mbili, hasa kwa barua pepe.")),
"accounttakeover": (["account takeover", "whatsapp scam", "whatsapp verification code scam", "hacked account", "social media account takeover", "verification code scam", "otp scam", "otp fraud"],
  ("Account takeover (WhatsApp and social media codes)", "Criminals trick you into giving the verification code sent to your phone, or a login link, then take over your WhatsApp or social account and message your contacts asking for money.", "A “friend” says “I sent my code to your number by mistake, please send it back”; it is really your own account's login code.", "Never share verification codes with anyone. Turn on two-step verification, and warn your contacts if your account is taken over."),
  ("Piratage de compte (codes WhatsApp et réseaux sociaux)", "Des criminels vous font donner le code de vérification reçu sur votre téléphone, ou un lien de connexion, puis prennent votre compte WhatsApp ou de réseau social et écrivent à vos contacts pour demander de l'argent.", "Un « ami » dit « Je t'ai envoyé mon code par erreur, renvoie-le-moi » ; c'est en réalité le code de connexion de votre propre compte.", "Ne partagez jamais un code de vérification. Activez la vérification en deux étapes et prévenez vos contacts si votre compte est pris."),
  ("Gufata konti (kode za WhatsApp n'imbuga nkoranyambaga)", "Abagizi ba nabi bakubeshya ngo ubahe kode yo kwemeza yoherejwe kuri telefoni yawe, cyangwa link yo kwinjira, hanyuma bagafata konti yawe ya WhatsApp cyangwa y'imbuga nkoranyambaga bakandikira abo muziranye basaba amafaranga.", "«Inshuti» ivuga iti «Nakohereje kode yanjye kuri nimero yawe kubera ikosa, nyisubize»; mu by'ukuri ni kode yo kwinjira kuri konti yawe.", "Ntuzigere usangiza kode yo kwemeza umuntu uwo ari we wese. Fungura two-step verification kandi umenyeshe abo muziranye niba konti yawe yafashwe."),
  ("Kuchukua akaunti (misimbo ya WhatsApp na mitandao ya kijamii)", "Wahalifu hukudanganya utoe msimbo wa uthibitisho uliotumwa kwa simu yako, au kiungo cha kuingia, kisha huchukua akaunti yako ya WhatsApp au mitandao ya kijamii na kuwaandikia anwani zako wakiomba pesa.", "«Rafiki» anasema «Nilikutumia msimbo wangu kimakosa, nirudishie»; kwa kweli ni msimbo wa kuingia kwenye akaunti yako.", "Usishiriki kamwe misimbo ya uthibitisho. Washa uthibitishaji wa hatua mbili na uwaonye anwani zako akaunti ikichukuliwa.")),
"fakeinvoice": (["fake invoice", "invoice scam", "fake bill", "fake payment request", "payment request scam"],
  ("Fake invoice and payment request", "A bill for a service or product you never ordered, or a copy of a real invoice with changed bank details, hoping staff pay without checking.", "An invoice for “domain renewal” arrives from a company you have never used.", "Check every invoice against your orders, confirm bank changes by phone, and pay only suppliers you have verified."),
  ("Fausse facture et fausse demande de paiement", "Une facture pour un service ou produit jamais commandé, ou la copie d'une vraie facture avec des coordonnées bancaires modifiées, en espérant que le personnel paie sans vérifier.", "Une facture de « renouvellement de domaine » arrive d'une société que vous n'avez jamais utilisée.", "Comparez chaque facture à vos commandes, confirmez les changements bancaires par téléphone et ne payez que des fournisseurs vérifiés."),
  ("Fagitire y'impimbano n'ubusabe bwo kwishyura", "Fagitire y'ikintu utigeze utumiza, cyangwa kopi ya fagitire nyayo ifite konti ya banki yahinduwe, bizeye ko abakozi bazishyura batagenzuye.", "Fagitire yo «kuvugurura domaine» iturutse ku kigo utigeze ukoresha.", "Genzura buri fagitire ugereranyije n'ibyo watumije, emeza impinduka za banki kuri telefoni, kandi wishyure abatanga ibicuruzwa wagenzuye gusa."),
  ("Ankara bandia na ombi la malipo", "Ankara ya huduma au bidhaa ambazo hukuagiza, au nakala ya ankara halisi yenye taarifa za benki zilizobadilishwa, wakitumaini wafanyakazi watalipa bila kuhakiki.", "Ankara ya «kuhuisha domaini» inafika kutoka kampuni ambayo hujawahi kuitumia.", "Linganisha kila ankara na oda zako, thibitisha mabadiliko ya benki kwa simu, na ulipe wasambazaji waliohakikiwa tu.")),
"pretexting": (["pretexting", "social engineering", "social engineer", "human hacking"],
  ("Pretexting and social engineering", "Manipulating people with an invented story (a pretext) such as a new colleague, auditor or delivery agent so that they give information or access willingly.", "Someone phones the office as an “IT technician” and asks a worker to read out a password to “fix” a problem.", "Verify identity independently, follow your organisation's rules, and never give passwords or codes to anyone, even someone who sounds official."),
  ("Prétexte et ingénierie sociale", "Manipuler des personnes avec une histoire inventée (un prétexte) — nouveau collègue, auditeur, livreur — pour qu'elles donnent volontairement informations ou accès.", "Quelqu'un appelle le bureau en « technicien informatique » et demande à un employé de lire un mot de passe pour « réparer » un problème.", "Vérifiez l'identité de façon indépendante, suivez les règles de votre organisation et ne donnez jamais mots de passe ou codes, même à quelqu'un qui paraît officiel."),
  ("Pretexting n'uburiganya bukoresha imitekerereze (social engineering)", "Kuyobya abantu ukoresheje inkuru yahimbwe (urwitwazo) nk'umukozi mushya, umugenzuzi cyangwa uwatwara ibicuruzwa ngo batange amakuru cyangwa uburenganzira ku bushake.", "Umuntu ahamagara ibiro yiyita «umutekinisiye wa IT» agasaba umukozi gusoma ijambo ry'ibanga ngo «akosore» ikibazo.", "Genzura uwo ari we mu buryo bwigenga, kurikiza amategeko y'ikigo cyawe, kandi ntugatange amajambo y'ibanga cyangwa kode, n'iyo uwo muntu yumvikana nk'ukomoka ku mpapuro."),
  ("Pretexting na uhandisi wa kijamii", "Kuwadanganya watu kwa hadithi iliyobuniwa (kisingizio) kama mfanyakazi mpya, mkaguzi au mletaji ili watoe taarifa au ufikiaji kwa hiari.", "Mtu anapiga ofisini kama «fundi wa TEHAMA» na kumwomba mfanyakazi asome nenosiri ili «arekebishe» tatizo.", "Hakiki utambulisho kwa kujitegemea, fuata kanuni za shirika lako, na usitoe kamwe nenosiri au misimbo, hata kwa mtu anayeonekana rasmi.")),
"baiting": (["baiting", "usb drop", "usb attack", "infected usb", "found usb", "free usb"],
  ("Baiting and infected USB drives", "Something tempting is left for you to find or is offered free, such as a USB stick labelled “salaries” or a free download, that infects your device when used.", "A USB drive is left near an office entrance and an employee plugs it into a work computer.", "Never plug in found USB drives or download “free” offers from unknown sources; hand found devices to IT or security."),
  ("Appât (baiting) et clés USB infectées", "Quelque chose de tentant est laissé à trouver ou offert gratuitement, comme une clé USB marquée « salaires » ou un téléchargement gratuit, qui infecte l'appareil quand on l'utilise.", "Une clé USB est laissée près de l'entrée d'un bureau et un employé la branche sur un ordinateur de travail.", "Ne branchez jamais une clé USB trouvée ni ne téléchargez d'offres « gratuites » de sources inconnues ; remettez les appareils trouvés au service informatique ou à la sécurité."),
  ("Baiting n'USB zanduye", "Ikintu gikurura gisigwa ngo ugisange cyangwa gitangwa ku buntu, nka USB yanditseho «imishahara» cyangwa ikintu cyo gukuramo cy'ubuntu, cyanduza igikoresho iyo ucyinjijemo.", "USB isigwa hafi y'umuryango w'ibiro maze umukozi ayishyira kuri mudasobwa y'akazi.", "Ntuzigere winjiza USB wabonye cyangwa ngo ukuremo ibintu «by'ubuntu» biturutse ku batazwi; ibikoresho wabonye ubishyikirize ushinzwe IT cyangwa umutekano."),
  ("Baiting na USB zilizoambukizwa", "Kitu cha kuvutia huachwa ukipate au hutolewa bure, kama USB yenye lebo «mishahara» au upakuaji wa bure, kinachoambukiza kifaa kikitumika.", "USB inaachwa karibu na mlango wa ofisi na mfanyakazi anaichomeka kwenye kompyuta ya kazi.", "Usichomeke kamwe USB uliyoiokota wala kupakua ofa za «bure» kutoka vyanzo visivyojulikana; kabidhi vifaa vilivyookotwa kwa TEHAMA au usalama.")),
"evilwifi": (["evil twin", "fake wifi", "fake wi-fi", "public wifi scam", "public wi-fi attack", "free wifi scam", "rogue hotspot", "man in the middle"],
  ("Fake Wi-Fi (evil twin) and public Wi-Fi attacks", "A criminal sets up a free hotspot with a believable name, or watches an open network, to see or alter what connected people send, including logins.", "A café's network name appears twice and you join the wrong one, which shows a fake login page.", "Avoid banking or logging in on open Wi-Fi, confirm the exact network name with staff, prefer mobile data for sensitive tasks, and use only secure (https) sites."),
  ("Faux Wi-Fi (evil twin) et attaques sur Wi-Fi public", "Un criminel crée un point d'accès gratuit au nom crédible, ou surveille un réseau ouvert, pour voir ou modifier ce que les connectés envoient, y compris les identifiants.", "Le nom du réseau d'un café apparaît deux fois et vous rejoignez le mauvais, qui affiche une fausse page de connexion.", "Évitez la banque ou les connexions sur Wi-Fi ouvert, confirmez le nom exact du réseau auprès du personnel, préférez les données mobiles pour les tâches sensibles et n'utilisez que des sites sécurisés (https)."),
  ("Wi-Fi y'impimbano (evil twin) n'ibitero kuri Wi-Fi rusange", "Umuhemu ashyiraho hotspot y'ubuntu ifite izina ryizewe, cyangwa akareba urusobe rufunguye, kugira ngo abone cyangwa ahindure ibyo abahujwe bohereza, harimo amakuru yo kwinjira.", "Izina rya Wi-Fi y'ikawa ryigaragaza kabiri ukinjira mu itari yo, ikerekana urupapuro rw'ibinyoma rwo kwinjiraho.", "Irinde gukora banki cyangwa kwinjira kuri Wi-Fi ifunguye, baza abakozi izina nyaryo ry'urusobe, ukoreshe data ya telefoni ku bintu by'ingenzi, kandi ukoreshe imbuga zifite https gusa."),
  ("Wi-Fi bandia (evil twin) na mashambulizi ya Wi-Fi ya umma", "Mhalifu huweka hotspot ya bure yenye jina linaloaminika, au hufuatilia mtandao wazi, ili kuona au kubadilisha wanachotuma waliounganishwa, ikiwemo taarifa za kuingia.", "Jina la mtandao wa mkahawa linaonekana mara mbili na unajiunga na lisilo sahihi, linaloonyesha ukurasa bandia wa kuingia.", "Epuka benki au kuingia kwenye Wi-Fi wazi, thibitisha jina kamili la mtandao na wafanyakazi, tumia data ya simu kwa mambo nyeti, na tumia tovuti salama (https) tu.")),
"fakeapp": (["fake app", "fake apps", "malicious app", "malicious apps", "fake mobile app", "fake loan app", "predatory loan app", "loan app scam", "fake loan apps"],
  ("Fake and malicious apps (including predatory loan apps)", "Apps that copy real ones or promise instant loans, then steal data, show ads, or demand contacts and photos, and sometimes threaten borrowers.", "A “quick loan” app asks for access to your contacts and photos, then messages your contacts if you are late.", "Install apps only from official stores, check the publisher and reviews, refuse permissions an app does not need, and borrow only from licensed lenders."),
  ("Fausses applications et applications malveillantes (dont prêts prédateurs)", "Des applications qui copient les vraies ou promettent des prêts instantanés, puis volent des données, affichent des publicités, exigent vos contacts et photos, et parfois menacent les emprunteurs.", "Une appli de « prêt rapide » demande l'accès à vos contacts et photos, puis écrit à vos contacts si vous êtes en retard.", "Installez des applications uniquement depuis les boutiques officielles, vérifiez l'éditeur et les avis, refusez les autorisations inutiles et n'empruntez qu'auprès de prêteurs agréés."),
  ("Porogaramu z'impimbano n'iz'ubugizi bwa nabi (harimo iz'inguzanyo z'ubwambuzi)", "Porogaramu zikopera iz'ukuri cyangwa zisezeranya inguzanyo zihuse, hanyuma ziyibe amakuru, zerekane amatangazo, zisabe abo muziranye n'amafoto, rimwe na rimwe zikangisha abaguze.", "Porogaramu y'«inguzanyo yihuse» ikubaza kugera ku bo muziranye n'amafoto, hanyuma ikandikira abo muziranye uramutse utinze kwishyura.", "Shyiraho porogaramu mu maduka y'ukuri gusa, reba uwayikoze n'ibitekerezo, wange uburenganzira budakenewe, kandi ugurize gusa ku bafite uruhushya."),
  ("Programu bandia na hasidi (pamoja na za mikopo ya unyonyaji)", "Programu zinazonakili halisi au kuahidi mikopo ya papo hapo, kisha kuiba data, kuonyesha matangazo, kudai anwani na picha zako, na wakati mwingine kuwatishia wakopaji.", "Programu ya «mkopo wa haraka» inaomba kufikia anwani na picha zako, kisha kuwaandikia anwani zako ukichelewa.", "Sakinisha programu kutoka maduka rasmi tu, hakiki mchapishaji na maoni, kataa ruhusa zisizohitajika, na ukope kutoka kwa wakopeshaji wenye leseni tu.")),
"deepfake": (["deepfake", "deepfakes", "voice cloning", "voice clone scam", "ai voice scam", "ai generated scam", "fake video scam", "synthetic media"],
  ("Deepfake and voice-cloning scams", "Criminals use AI to copy a voice, face or video of someone you trust (a relative, boss or public figure) to ask for money or to promote a fake investment.", "A voice message that sounds like your child says they are in trouble and need money at once.", "Pause and verify by calling back on a known number or asking a question only the real person can answer; agree a family code word; distrust urgent money requests even if the voice sounds right."),
  ("Deepfakes et clonage de voix", "Des criminels utilisent l'IA pour copier la voix, le visage ou la vidéo d'une personne de confiance (proche, patron, personnalité) afin de demander de l'argent ou de promouvoir un faux investissement.", "Un message vocal qui ressemble à votre enfant dit qu'il a des ennuis et a besoin d'argent tout de suite.", "Faites une pause et vérifiez en rappelant un numéro connu ou en posant une question que seule la vraie personne peut résoudre ; convenez d'un mot de code familial ; méfiez-vous des demandes d'argent urgentes même si la voix paraît juste."),
  ("Deepfake no gukopera ijwi (voice cloning)", "Abagizi ba nabi bakoresha AI gukopera ijwi, isura cyangwa video by'umuntu wizeye (mwene wanyu, umuyobozi cyangwa icyamamare) kugira ngo basabe amafaranga cyangwa bamamaze ishoramari ry'impimbano.", "Ubutumwa bw'ijwi busa n'umwana wawe buvuga ko ari mu kaga akeneye amafaranga ako kanya.", "Hagarara ugenzure uhamagaye kuri nimero izwi cyangwa ubaza ikibazo gusa uwo muntu nyakuri yasubiza; mwemeranye ijambo ry'ibanga mu muryango; wirinde ubusabe bw'amafaranga bwihutirwa n'iyo ijwi risa neza."),
  ("Deepfake na kunakili sauti (voice cloning)", "Wahalifu hutumia AI kunakili sauti, uso au video ya mtu unayemwamini (ndugu, bosi au mtu maarufu) ili kuomba pesa au kutangaza uwekezaji bandia.", "Ujumbe wa sauti unaosikika kama mtoto wako unasema yuko matatani na anahitaji pesa mara moja.", "Simama na uhakiki kwa kupiga tena kwa namba inayojulikana au kuuliza swali ambalo mtu halisi pekee anaweza kujibu; kubaliana neno la siri la familia; usiamini maombi ya pesa ya haraka hata sauti ikisikika sahihi.")),
"sextortion": (["sextortion", "blackmail scam", "online blackmail", "sexual blackmail", "nude photo blackmail"],
  ("Sextortion and online blackmail", "A criminal threatens to share private photos, videos or messages (real, stolen or faked) unless you pay or send more. It often starts with a friendly stranger or a fake profile.", "A new online “friend” moves the chat to video and then threatens to share the recording with your family unless you pay.", "Do not pay and do not send more material. Stop contact, keep screenshots, block and report the account, and tell a trusted adult or the police. You are the victim, not the one at fault."),
  ("Sextorsion et chantage en ligne", "Un criminel menace de diffuser des photos, vidéos ou messages privés (réels, volés ou truqués) si vous ne payez pas ou n'envoyez pas plus. Cela commence souvent par un inconnu sympathique ou un faux profil.", "Un nouvel « ami » en ligne passe au chat vidéo puis menace d'envoyer l'enregistrement à votre famille si vous ne payez pas.", "Ne payez pas et n'envoyez rien de plus. Coupez le contact, gardez des captures d'écran, bloquez et signalez le compte, et parlez à un adulte de confiance ou à la police. Vous êtes la victime, pas le fautif."),
  ("Sextortion no gushyira ku gitutu kuri interineti", "Umuhemu akangisha gusangiza amafoto, video cyangwa ubutumwa bwite (nyabyo, bwibwe cyangwa bwahimbwe) keretse wishyuye cyangwa wohereje ibindi. Akenshi bitangira n'umuntu utazi usa n'incuti cyangwa konti y'impimbano.", "«Inshuti» nshya kuri interineti ihindura ikiganiro kuri video hanyuma ikakangisha gusangiza amashusho umuryango wawe keretse wishyuye.", "Ntukishyure kandi ntugohereze ibindi. Hagarika itumanaho, bika amafoto ya ecran, hagarika kandi utange raporo kuri konti, ubibwire umuntu mukuru wizeye cyangwa polisi. Ni wowe wagizweho ingaruka, si wowe ufite amakosa."),
  ("Sextortion na ulaghai wa vitisho mtandaoni", "Mhalifu anatishia kushiriki picha, video au jumbe za faragha (halisi, zilizoibwa au bandia) usipolipa au kutuma zaidi. Mara nyingi huanza na mgeni rafiki au akaunti bandia.", "«Rafiki» mpya mtandaoni anahamishia gumzo kwenye video kisha kutishia kushiriki rekodi na familia yako usipolipa.", "Usilipe wala kutuma zaidi. Acha mawasiliano, hifadhi picha za skrini, mzuie na uripoti akaunti, na umwambie mtu mzima unayemwamini au polisi. Wewe ni mwathiriwa, si mwenye kosa.")),
"overpayment": (["overpayment scam", "fake payment proof", "fake payment confirmation", "marketplace scam", "classified ads scam", "buyer scam", "seller scam", "fake escrow"],
  ("Marketplace, overpayment and fake-payment scams", "On classified or social-media sales, a fake buyer sends a fake payment confirmation or “overpays” and asks for the difference back; or a fake seller takes a deposit and vanishes.", "A buyer shows a payment screenshot, then asks you to send the “delivery fee” to a courier before you see the money.", "Confirm money has actually arrived in your own account or wallet (not from a screenshot or message), meet in safe public places, and avoid paying deposits to sellers you cannot verify."),
  ("Arnaques sur les marchés en ligne, trop-perçu et faux paiements", "Dans les ventes d'annonces ou sur réseaux sociaux, un faux acheteur envoie une fausse confirmation de paiement ou « paie trop » et demande le surplus ; ou un faux vendeur prend un acompte et disparaît.", "Un acheteur montre une capture de paiement puis demande d'envoyer des « frais de livraison » à un coursier avant que vous voyiez l'argent.", "Vérifiez que l'argent est bien arrivé sur votre compte ou portefeuille (pas par capture ou message), rencontrez-vous dans des lieux publics sûrs et évitez de verser des acomptes à des vendeurs invérifiables."),
  ("Uburiganya ku isoko ryo kuri interineti, kwishyura birenze n'ubwishyu bw'ibinyoma", "Mu igurisha ry'amatangazo cyangwa ku mbuga nkoranyambaga, umuguzi w'impimbano yohereza ikimenyetso cy'ubwishyu cy'ibinyoma cyangwa «yishyura birenze» agasaba gusubizwa itandukaniro; cyangwa umugurisha w'impimbano afata avansi agacika.", "Umuguzi akwereka ifoto y'ubwishyu hanyuma agusaba kohereza «amafaranga yo gutwara» umutwaye mbere y'uko ubona amafaranga.", "Emeza ko amafaranga yageze kuri konti yawe nyayo (si ku ifoto cyangwa ubutumwa), mukorere mu bibanza rusange bitekanye, kandi wirinde gutanga avansi ku bagurisha utagenzuye."),
  ("Ulaghai wa soko la mtandaoni, malipo ya ziada na malipo bandia", "Kwenye mauzo ya matangazo au mitandao ya kijamii, mnunuzi bandia hutuma uthibitisho bandia wa malipo au «hulipa zaidi» na kuomba tofauti irudishwe; au muuzaji bandia huchukua kiasi cha awali na kutoweka.", "Mnunuzi anaonyesha picha ya malipo kisha anakuomba utume «ada ya usafirishaji» kwa mtoa huduma kabla hujaona pesa.", "Thibitisha pesa zimefika kweli kwenye akaunti au pochi yako (si kwa picha au ujumbe), kutana sehemu salama za umma, na epuka kulipa amana kwa wauzaji usiowahakiki.")),
"rental": (["rental scam", "housing scam", "fake rental", "fake property", "land scam", "real estate scam", "fake landlord"],
  ("Rental, housing and land scams", "A fake landlord or agent advertises a house, room or plot at a low price, collects a deposit or “viewing fee”, and disappears, or sells land or property they do not own.", "A listing with attractive photos asks for a deposit before any visit, and the “owner” says they are abroad.", "Visit in person, check ownership documents with the official land or local authority, never pay before seeing the property, and be wary of owners who cannot meet."),
  ("Arnaques à la location, au logement et aux terrains", "Un faux propriétaire ou agent annonce une maison, une chambre ou une parcelle à bas prix, encaisse un acompte ou des « frais de visite » et disparaît, ou vend un terrain ou un bien qui ne lui appartient pas.", "Une annonce aux belles photos demande un acompte avant toute visite, et le « propriétaire » dit être à l'étranger.", "Visitez en personne, vérifiez les titres auprès de l'autorité foncière ou locale officielle, ne payez jamais avant d'avoir vu le bien et méfiez-vous des propriétaires qui refusent de vous rencontrer."),
  ("Uburiganya mu gukodesha, amacumbi n'ubutaka", "Nyir'inzu cyangwa umukomisiyoneri w'impimbano atangaza inzu, icyumba cyangwa ikibanza ku giciro gito, akakira avansi cyangwa «amafaranga yo gusura» agacika, cyangwa agurisha ubutaka cyangwa umutungo utari uwe.", "Itangazo rifite amafoto meza risaba avansi mbere yo gusura, kandi «nyirayo» akavuga ko ari mu mahanga.", "Sura wowe ubwawe, genzura ibyangombwa by'ubutaka ku rwego rubifite, ntuzigere wishyura mbere yo kubona umutungo, kandi wirinde abanga guhura nawe."),
  ("Ulaghai wa kodi, nyumba na ardhi", "Mwenye nyumba au wakala bandia anatangaza nyumba, chumba au kiwanja kwa bei ndogo, anakusanya amana au «ada ya kutazama» na kutoweka, au kuuza ardhi au mali asiyomiliki.", "Tangazo lenye picha nzuri linaomba amana kabla ya ziara yoyote, na «mmiliki» anasema yuko nje ya nchi.", "Tembelea mwenyewe, hakiki hati za umiliki kwa mamlaka rasmi ya ardhi au ya mtaa, usilipe kamwe kabla ya kuona mali, na jihadhari na wamiliki wasioweza kukutana.")),
"scholarship": (["scholarship scam", "visa scam", "immigration scam", "fake scholarship", "study abroad scam", "fake visa"],
  ("Scholarship, visa and travel scams", "Offers of guaranteed scholarships, visas, work abroad or lottery visas for a fee, or fake agents who take money for travel documents that never arrive.", "A message guarantees a visa within a week for an “agent fee” paid to a personal number.", "Apply only through official embassy, school or government websites, never pay a personal account, and treat “guaranteed” visas or scholarships as a red flag."),
  ("Arnaques aux bourses, visas et voyages", "Offres de bourses, visas ou travail à l'étranger garantis contre paiement, ou faux agents qui prennent de l'argent pour des documents de voyage qui n'arrivent jamais.", "Un message garantit un visa en une semaine contre des « frais d'agent » payés à un numéro personnel.", "Postulez uniquement via les sites officiels d'ambassades, d'écoles ou de gouvernements, ne payez jamais un compte personnel et considérez « garanti » comme un signal d'alerte."),
  ("Uburiganya bwa buruse, viza n'ingendo", "Amasezerano ya buruse, viza cyangwa akazi mu mahanga byemejwe kubera amafaranga, cyangwa abakomisiyoneri b'impimbano bafata amafaranga y'ibyangombwa by'urugendo bitigera bizaza.", "Ubutumwa bwemeza viza mu cyumweru kimwe kubera «amafaranga y'umukomisiyoneri» yishyurwa nimero bwite.", "Saba gusa ukoresheje imbuga z'ukuri za ambasade, ishuri cyangwa leta, ntukishyure konti bwite, kandi «byemejwe» ubifate nk'ikimenyetso cy'ububi."),
  ("Ulaghai wa udhamini wa masomo, visa na safari", "Ofa za udhamini wa uhakika, visa au kazi nje ya nchi kwa ada, au mawakala bandia wanaochukua pesa kwa hati za kusafiri ambazo hazifiki.", "Ujumbe unahakikisha visa ndani ya wiki moja kwa «ada ya wakala» inayolipwa kwa namba binafsi.", "Omba kupitia tovuti rasmi za ubalozi, shule au serikali tu, usilipe akaunti binafsi, na uone «uhakika» kama ishara ya hatari.")),
"giveaway": (["fake giveaway", "social media giveaway scam", "giveaway scam", "free data scam", "free airtime scam", "free gift scam", "like and share scam", "survey scam"],
  ("Fake giveaways, surveys and “free” offers", "Posts or messages promise free data, airtime, phones or gifts if you click, share, complete a survey or pay delivery, to harvest your details, spread the scam or take small payments.", "“Share this message with 10 friends to get free data.” The link asks for your phone number and a code.", "Treat free offers with caution, check the official page of the brand, do not enter codes or personal details, and do not forward chain messages."),
  ("Faux jeux-concours, sondages et offres « gratuites »", "Des publications ou messages promettent des données, du crédit, des téléphones ou des cadeaux gratuits si vous cliquez, partagez, remplissez un sondage ou payez la livraison, pour récolter vos données, propager l'arnaque ou prélever de petits paiements.", "« Partagez ce message à 10 amis pour recevoir des données gratuites. » Le lien demande votre numéro et un code.", "Méfiez-vous des offres gratuites, vérifiez la page officielle de la marque, ne saisissez ni codes ni données personnelles et ne transférez pas les messages en chaîne."),
  ("Imikino y'impimbano, ubushakashatsi n'ibyo «by'ubuntu»", "Ubutumwa busezeranya data, airtime, telefoni cyangwa impano z'ubuntu niba ukanze, usangije, wuzuza ubushakashatsi cyangwa wishyuye ubwikorezi, kugira ngo bwegeranye amakuru yawe, bukwirakwize uburiganya cyangwa bwake amafaranga make.", "«Sangiza ubu butumwa inshuti 10 ubone data y'ubuntu.» Link ikubaza nimero na kode.", "Wirinde ibyo by'ubuntu, reba urupapuro rw'ukuri rw'ikirango, ntugashyiremo kode cyangwa amakuru bwite, kandi ntugasangize ubutumwa bw'inyuma."),
  ("Zawadi bandia, tafiti na ofa za «bure»", "Machapisho au jumbe zinaahidi data, muda wa maongezi, simu au zawadi bure ukibonyeza, kushiriki, kujaza utafiti au kulipia usafirishaji, ili kukusanya taarifa zako, kueneza ulaghai au kuchukua malipo madogo.", "«Shiriki ujumbe huu kwa marafiki 10 upate data bure.» Kiungo kinaomba namba yako na msimbo.", "Chukulia ofa za bure kwa tahadhari, angalia ukurasa rasmi wa chapa, usiweke misimbo au taarifa binafsi, na usisambaze jumbe za mnyororo.")),
"malvertising": (["malvertising", "malicious ads", "fake ads", "fake advert", "clickjacking", "seo poisoning", "fake search result", "fake download button", "scareware"],
  ("Malicious ads, clickjacking and fake download buttons", "Adverts, search results or hidden buttons that lead to fake sites or downloads, or that trick your click into doing something else, such as installing software or confirming a payment.", "A search result for a popular program is an ad that leads to a copy site offering an infected installer.", "Download only from the official publisher's site, type addresses yourself for banking, use an ad blocker, and close pop-ups instead of clicking inside them."),
  ("Publicités malveillantes, détournement de clic et faux boutons de téléchargement", "Publicités, résultats de recherche ou boutons cachés qui mènent à de faux sites ou téléchargements, ou qui détournent votre clic pour installer un logiciel ou confirmer un paiement.", "Un résultat de recherche pour un programme populaire est une publicité qui mène à un site copie proposant un installateur infecté.", "Téléchargez uniquement depuis le site de l'éditeur officiel, saisissez vous-même les adresses bancaires, utilisez un bloqueur de publicités et fermez les fenêtres au lieu de cliquer dedans."),
  ("Amatangazo mabi, clickjacking n'utubuto tw'ubukure tw'impimbano", "Amatangazo, ibisubizo by'ishakisha cyangwa utubuto duhishe tuyobora ku mbuga cyangwa ibyo gukuramo by'impimbano, cyangwa tuyobya ukanda ngo ushyireho porogaramu cyangwa wemeze ubwishyu.", "Igisubizo cy'ishakisha cya porogaramu izwi ni itangazo riyobora ku rubuga rukopera rutanga installer yanduye.", "Kuramo gusa ku rubuga rw'uwayikoze nyawe, andika wowe ubwawe aderesi za banki, koresha ad blocker, kandi ufunge pop-ups aho gukandamo."),
  ("Matangazo hasidi, clickjacking na vitufe bandia vya kupakua", "Matangazo, matokeo ya utafutaji au vitufe vilivyofichwa vinavyoelekeza kwenye tovuti au vipakuliwa bandia, au kukudanganya ubonyeze kusakinisha programu au kuthibitisha malipo.", "Matokeo ya utafutaji wa programu maarufu ni tangazo linaloelekeza kwenye tovuti nakala inayotoa kisakinishi kilichoambukizwa.", "Pakua kutoka tovuti rasmi ya mchapishaji tu, andika anwani za benki mwenyewe, tumia kizuia matangazo, na funga madirisha badala ya kubonyeza ndani yake.")),
"typosquatting": (["typosquatting", "lookalike domain", "look-alike website", "spoofed website", "domain spoofing", "fake domain", "email spoofing", "spoofing"],
  ("Look-alike websites and spoofing (typosquatting)", "Fake sites or email addresses with spellings almost identical to a real one (for example a swapped or added letter), or sender names forged to look genuine.", "An address like “bnk-rwanda-secure.example” looks like a bank site but is a copy.", "Check the exact spelling of the address and the sender, bookmark important sites, and be wary when the address has extra words or characters."),
  ("Sites sosies et usurpation (typosquatting)", "Faux sites ou adresses e-mail dont l'orthographe est presque identique à celle d'un vrai (lettre inversée ou ajoutée), ou noms d'expéditeur falsifiés pour paraître authentiques.", "Une adresse comme « bnk-rwanda-secure.example » ressemble à un site de banque mais en est une copie.", "Vérifiez l'orthographe exacte de l'adresse et de l'expéditeur, mettez les sites importants en favoris et méfiez-vous des adresses avec des mots ou caractères en plus."),
  ("Imbuga zisa n'iz'ukuri no kwiyitirira (typosquatting)", "Imbuga cyangwa aderesi za imeri z'impimbano zifite imyandikire hafi ya kimwe n'iy'ukuri (inyuguti yahinduwe cyangwa yongewemo), cyangwa amazina y'uwohereje yahimbwe.", "Aderesi nka «bnk-rwanda-secure.example» isa n'urubuga rwa banki ariko ni kopi.", "Reba imyandikire nyayo y'aderesi n'uwohereje, bika imbuga z'ingenzi nk'ibikundwa, kandi wirinde aderesi zifite amagambo cyangwa inyuguti zirenga."),
  ("Tovuti zinazofanana na halisi na kughushi (typosquatting)", "Tovuti au anwani bandia za barua pepe zenye tahajia karibu sawa na halisi (herufi iliyobadilishwa au kuongezwa), au majina ya mtumaji yaliyoghushiwa kuonekana halisi.", "Anwani kama «bnk-rwanda-secure.example» inaonekana kama tovuti ya benki lakini ni nakala.", "Angalia tahajia kamili ya anwani na mtumaji, weka alama tovuti muhimu, na jihadhari anwani ikiwa na maneno au herufi za ziada.")),
"cardskimming": (["card skimming", "atm skimming", "skimmer", "atm scam", "card fraud", "card cloning", "card not present fraud", "shoulder surfing"],
  ("Card skimming, ATM and card fraud", "Devices or people copy card details or PINs at ATMs, shops or online, for example a hidden reader on a machine, a camera, or someone watching you enter your PIN.", "A loose or bulky card slot on an ATM hides a reader, and a tiny camera records the PIN.", "Cover the keypad, inspect the card slot, use ATMs inside banks, turn on transaction alerts, and report lost cards or unknown charges at once."),
  ("Écrémage de cartes, fraude au distributeur et à la carte", "Des dispositifs ou des personnes copient les données de carte ou le PIN aux distributeurs, en magasin ou en ligne : lecteur caché, caméra, ou quelqu'un qui regarde votre code.", "Une fente de carte lâche ou épaisse cache un lecteur et une minuscule caméra enregistre le PIN.", "Cachez le clavier, inspectez la fente, utilisez les distributeurs à l'intérieur des banques, activez les alertes de transaction et signalez immédiatement une carte perdue ou un débit inconnu."),
  ("Kwiba amakuru ya karita (skimming), ATM n'uburiganya bwa karita", "Ibikoresho cyangwa abantu bakopera amakuru ya karita cyangwa PIN kuri ATM, mu maduka cyangwa kuri interineti: ikoresho gihishe, kamera, cyangwa umuntu urebera iyo wandika PIN.", "Aho bashyira karita hakubiswe cyangwa hunguruye hahishe ikoresho gisoma, kandi kamera ntoya ikandika PIN.", "Hisha clavier, reba aho bashyira karita, koresha ATM zo mu nzu za banki, fungura ubutumwa bw'ibikorwa, kandi utange raporo vuba ya karita yatakaye cyangwa amafaranga atazwi."),
  ("Kuiba data za kadi (skimming), ATM na ulaghai wa kadi", "Vifaa au watu hunakili taarifa za kadi au PIN kwenye ATM, maduka au mtandaoni: kisomaji kilichofichwa, kamera, au mtu anayetazama unapoweka PIN.", "Sehemu ya kuingiza kadi iliyolegea au nene inaficha kisomaji, na kamera ndogo inarekodi PIN.", "Funika kibodi, kagua sehemu ya kadi, tumia ATM ndani ya benki, washa arifa za miamala, na ripoti kadi iliyopotea au makato yasiyojulikana mara moja.")),
"familyemergency": (["family emergency scam", "grandparent scam", "relative in trouble scam", "hi mum scam", "hi dad scam", "new number scam", "friend in trouble scam"],
  ("Family and friend emergency scam", "A message or call, often “Hi, this is my new number”, claims to be a relative or friend in trouble (accident, arrest, hospital) and begs for urgent money.", "“Mum, I lost my phone, this is my new number. Please send money for an urgent bill.”", "Pause and call your relative on their old, known number or ask a personal question. Do not send money based on a text alone."),
  ("Arnaque à l'urgence familiale ou amicale", "Un message ou appel, souvent « Salut, c'est mon nouveau numéro », prétend venir d'un proche en difficulté (accident, arrestation, hôpital) et supplie d'envoyer de l'argent d'urgence.", "« Maman, j'ai perdu mon téléphone, voici mon nouveau numéro. Envoie de l'argent pour une facture urgente. »", "Faites une pause et appelez votre proche sur son ancien numéro connu ou posez une question personnelle. N'envoyez pas d'argent sur la base d'un seul SMS."),
  ("Uburiganya bw'ikibazo cyihutirwa cy'umuryango cyangwa incuti", "Ubutumwa cyangwa guhamagara, akenshi «Muraho, iyi ni nimero yanjye nshya», bwiyitirira mwene wanyu cyangwa incuti iri mu kaga (impanuka, gufungwa, ibitaro) busaba amafaranga byihutirwa.", "«Mama, natakaje telefoni, iyi ni nimero yanjye nshya. Ohereza amafaranga ya fagitire yihutirwa.»", "Hagarara uhamagare mwene wanyu kuri nimero ye ya kera izwi cyangwa ubaze ikibazo bwite. Ntukohereze amafaranga ku butumwa bumwe gusa."),
  ("Ulaghai wa dharura ya familia au rafiki", "Ujumbe au simu, mara nyingi «Habari, hii ni namba yangu mpya», unajidai kuwa ndugu au rafiki aliye matatani (ajali, kukamatwa, hospitali) na kuomba pesa haraka.", "«Mama, nimepoteza simu, hii ni namba yangu mpya. Tuma pesa kwa bili ya dharura.»", "Simama na umpigie ndugu yako kwa namba yake ya zamani inayojulikana au uulize swali la kibinafsi. Usitume pesa kwa ujumbe mmoja tu.")),
"refund": (["refund scam", "overcharge refund scam", "subscription scam", "fake subscription", "fake renewal", "unwanted charge scam", "fake delivery"],
  ("Refund, subscription and fake-delivery scams", "A message or call says you were charged for a subscription, a parcel needs a fee, or you are owed a refund, and asks you to click, call or give remote access to “fix” it.", "An SMS says “You were charged for a premium service, call this number to cancel” and the caller asks to see your screen.", "Check charges in your own account or app, not through the contact in the message. Never give remote access or codes to “process a refund”."),
  ("Arnaques au remboursement, à l'abonnement et à la fausse livraison", "Un message ou appel dit qu'on vous a débité un abonnement, qu'un colis nécessite des frais, ou qu'on vous doit un remboursement, et demande de cliquer, appeler ou donner un accès à distance pour « régler » cela.", "Un SMS dit « Un service premium vous a été facturé, appelez ce numéro pour annuler » et l'appelant demande à voir votre écran.", "Vérifiez les prélèvements dans votre propre compte ou application, pas via le contact du message. Ne donnez jamais d'accès à distance ni de codes pour « traiter un remboursement »."),
  ("Uburiganya bwo gusubizwa amafaranga, kwiyandikisha no gutwara ibicuruzwa by'impimbano", "Ubutumwa cyangwa guhamagara buvuga ko wakuweho amafaranga y'iyandikisha, ko igicuruzwa gisaba amafaranga, cyangwa ko ugomba gusubizwa, bugusaba gukanda, guhamagara cyangwa gutanga uburenganzira bwo kugenzura kure ngo «bukosore».", "SMS ivuga ngo «Wakuweho amafaranga ya serivisi ya premium, hamagara iyi nimero uhagarike» maze uhamagaye agasaba kureba ecran yawe.", "Reba amafaranga ayo ari yo muri konti cyangwa porogaramu yawe, si kuri contact iri mu butumwa. Ntugatange uburenganzira bwo kugenzura kure cyangwa kode ngo «bakubikire»."),
  ("Ulaghai wa marejesho, usajili na uwasilishaji bandia", "Ujumbe au simu unasema ulitozwa usajili, kifurushi kinahitaji ada, au unadaiwa marejesho, na kukuomba ubonyeze, upige au utoe ufikiaji wa mbali ili «kurekebisha».", "SMS inasema «Ulitozwa huduma ya premium, piga namba hii kughairi» na mpigaji anaomba kuona skrini yako.", "Angalia makato kwenye akaunti au programu yako, si kupitia mawasiliano ya ujumbe. Usitoe ufikiaji wa mbali wala misimbo ili «kushughulikia marejesho».")),
"fakeupdate": (["fake update", "fake software update", "fake browser update", "fake security update", "software supply chain attack", "supply chain attack", "fake patch"],
  ("Fake updates and supply-chain attacks", "A pop-up or message says your browser or system needs an urgent update, but the file is malware; in supply-chain attacks, a trusted supplier's real software or update is secretly tampered with.", "A web page says “Your browser is out of date, click to update” and downloads an unknown program.", "Update only through your device's built-in update settings or the official store, and get software from the original publisher."),
  ("Fausses mises à jour et attaques sur la chaîne d'approvisionnement", "Une fenêtre ou un message dit que votre navigateur ou système a besoin d'une mise à jour urgente, mais le fichier est un malware ; dans les attaques de chaîne d'approvisionnement, le vrai logiciel ou la mise à jour d'un fournisseur de confiance est piraté en secret.", "Une page web dit « Votre navigateur est obsolète, cliquez pour mettre à jour » et télécharge un programme inconnu.", "Mettez à jour uniquement via les réglages intégrés de l'appareil ou la boutique officielle, et obtenez les logiciels auprès de l'éditeur d'origine."),
  ("Amavugurura y'impimbano n'ibitero ku murongo w'itangwa", "Idirishya cyangwa ubutumwa buvuga ko browser cyangwa sisitemu yawe ikeneye kuvugururwa byihutirwa, ariko dosiye ni malware; mu bitero ku murongo w'itangwa, porogaramu nyayo cyangwa ivugurura ry'utanga wizewe ryahinduwe rwihishwa.", "Urupapuro rw'urubuga rukubwira ngo «Browser yawe irashaje, kanda uvugurure» rugakuramo porogaramu itazwi.", "Vugurura gusa ukoresheje igenamiterere ry'igikoresho cyangwa ububiko bw'ukuri, kandi ubone porogaramu ku wayikoze w'umwimerere."),
  ("Masasisho bandia na mashambulizi ya mnyororo wa ugavi", "Dirisha au ujumbe unasema kivinjari au mfumo wako unahitaji sasisho la dharura, lakini faili ni programu hasidi; katika mashambulizi ya mnyororo wa ugavi, programu halisi au sasisho la msambazaji unayemwamini linaharibiwa kwa siri.", "Ukurasa wa wavuti unasema «Kivinjari chako ni cha zamani, bonyeza kusasisha» na kupakua programu isiyojulikana.", "Sasisha kupitia mipangilio ya kifaa au duka rasmi pekee, na upate programu kutoka kwa mchapishaji asili.")),
"identitytheft": (["identity theft", "identity fraud", "data breach scam", "stolen identity", "id theft", "document fraud", "fake id"],
  ("Identity theft and data-breach fraud", "Criminals collect your personal details (ID number, date of birth, photos of documents) from leaks, phishing or careless sharing, and use them to open accounts, take loans or impersonate you.", "A copy of your ID sent to a stranger “for verification” is later used to register a mobile-money line in your name.", "Share ID copies only when truly necessary and write the purpose on them, report lost documents, check your accounts and registered lines regularly, and use unique passwords."),
  ("Vol d'identité et fraude après fuite de données", "Des criminels collectent vos données personnelles (numéro d'identité, date de naissance, photos de documents) via des fuites, du phishing ou un partage imprudent, et s'en servent pour ouvrir des comptes, contracter des prêts ou se faire passer pour vous.", "Une copie de votre pièce d'identité envoyée à un inconnu « pour vérification » sert ensuite à enregistrer une ligne mobile money à votre nom.", "Ne partagez des copies d'identité que si nécessaire et écrivez-y l'objet, signalez les documents perdus, vérifiez régulièrement vos comptes et lignes enregistrées et utilisez des mots de passe uniques."),
  ("Kwiba umwirondoro n'uburiganya nyuma yo kumeneka kw'amakuru", "Abagizi ba nabi bakusanya amakuru yawe bwite (nimero y'indangamuntu, itariki y'amavuko, amafoto y'ibyangombwa) mu mena, phishing cyangwa gusangiza nabi, bakayakoresha gufungura konti, gufata inguzanyo cyangwa kukwiyitirira.", "Kopi y'indangamuntu yawe yoherejwe umuntu utazi «ngo isuzumwe» nyuma ikoreshwa kwandikisha umurongo wa mobile money mu izina ryawe.", "Sangiza kopi z'indangamuntu gusa iyo ari ngombwa kandi wandike impamvu kuri zo, tanga raporo y'ibyangombwa byatakaye, genzura konti n'imirongo yanditse ku izina ryawe buri gihe, kandi ukoreshe amajambo y'ibanga yihariye."),
  ("Wizi wa utambulisho na ulaghai baada ya uvujaji wa data", "Wahalifu hukusanya taarifa zako binafsi (namba ya kitambulisho, tarehe ya kuzaliwa, picha za hati) kutoka uvujaji, hadaa au kushiriki kwa uzembe, na kuzitumia kufungua akaunti, kuchukua mikopo au kukuiga.", "Nakala ya kitambulisho chako iliyotumwa kwa mgeni «kwa uhakiki» baadaye inatumika kusajili laini ya pesa za simu kwa jina lako.", "Shiriki nakala za kitambulisho tu inapobidi na uandike madhumuni juu yake, ripoti hati zilizopotea, kagua akaunti na laini zilizosajiliwa mara kwa mara, na tumia nenosiri za kipekee.")),
"ddosextortion": (["ddos extortion", "ddos attack", "denial of service", "denial-of-service attack", "dos attack", "ransom ddos", "website extortion"],
  ("DDoS attacks and extortion", "Attackers flood a website or service with traffic so that it stops working, sometimes demanding payment to stop or threatening an attack unless a fee is paid.", "A small online shop's site goes down during a sale and an email demands payment to stop the attack.", "Use a reputable hosting or protection provider, keep contact with them, do not pay extortion demands, and report the incident."),
  ("Attaques DDoS et extorsion", "Des attaquants inondent un site ou service de trafic pour qu'il cesse de fonctionner, parfois en exigeant un paiement pour arrêter ou en menaçant d'attaquer si une somme n'est pas versée.", "Le site d'une petite boutique en ligne tombe pendant une vente et un e-mail exige un paiement pour arrêter l'attaque.", "Utilisez un hébergeur ou service de protection réputé, gardez le contact avec lui, ne payez pas les demandes d'extorsion et signalez l'incident."),
  ("Ibitero bya DDoS no gukangisha", "Abagizi ba nabi buzuza urubuga cyangwa serivisi n'urujya n'uruza ku buryo ihagarara gukora, rimwe na rimwe basaba kwishyura ngo bahagarike cyangwa bakangisha igitero keretse hishyuwe.", "Urubuga rw'iduka rito ryo kuri interineti ruhagarara mu gihe cy'igurisha maze imeri igasaba kwishyura ngo igitero gihagarare.", "Koresha utanga serivisi z'urubuga cyangwa uburinzi uzwi, komeza kuvugana na we, ntukishyure ibyo bagusaba, kandi utange raporo."),
  ("Mashambulizi ya DDoS na ulaghai wa vitisho", "Washambuliaji hujaza tovuti au huduma na trafiki hadi ikome, wakati mwingine wakidai malipo ili kusimamisha au kutishia shambulio usipolipa ada.", "Tovuti ya duka dogo la mtandaoni inazimika wakati wa mauzo na barua pepe inadai malipo kusimamisha shambulio.", "Tumia mtoa huduma wa upangishaji au ulinzi anayeaminika, endelea kuwasiliana naye, usilipe madai ya vitisho, na ripoti tukio.")),
"insider": (["insider threat", "insider fraud", "dishonest employee", "internal fraud", "employee fraud", "sim registration fraud"],
  ("Insider threats and internal fraud", "A dishonest or careless employee, agent or contractor misuses access to steal money or data, sell customer information, or help outside criminals.", "A staff member with system access quietly moves customers' money or sells their phone numbers.", "Give each person only the access they need, require two approvals for money moves, keep activity logs, review them, and offer a safe way to report suspicious behaviour."),
  ("Menaces internes et fraude interne", "Un employé, agent ou prestataire malhonnête ou négligent abuse de son accès pour voler de l'argent ou des données, vendre des informations de clients ou aider des criminels extérieurs.", "Un employé ayant accès au système déplace discrètement l'argent des clients ou vend leurs numéros de téléphone.", "Donnez à chacun seulement l'accès nécessaire, exigez deux validations pour les mouvements d'argent, conservez et examinez les journaux d'activité et offrez un moyen sûr de signaler un comportement suspect."),
  ("Ibitero biturutse imbere mu kigo n'uburiganya bw'imbere", "Umukozi, umukozi wa agent cyangwa uwatsindiye isoko utizewe cyangwa udashishoza akoresha nabi uburenganzira bwe kwiba amafaranga cyangwa amakuru, kugurisha amakuru y'abakiriya cyangwa gufasha abagizi ba nabi bo hanze.", "Umukozi ufite uburenganzira bwa sisitemu yimura rwihishwa amafaranga y'abakiriya cyangwa agurisha nimero zabo za telefoni.", "Haha buri wese uburenganzira akeneye gusa, saba kwemezwa kabiri ku migendekere y'amafaranga, bika kandi usuzume amateka y'ibikorwa, kandi utange inzira itekanye yo gutanga raporo ku myitwarire ikemangwa."),
  ("Vitisho vya ndani na ulaghai wa ndani", "Mfanyakazi, wakala au mkandarasi asiye mwaminifu au mzembe hutumia vibaya ufikiaji wake kuiba pesa au data, kuuza taarifa za wateja au kuwasaidia wahalifu wa nje.", "Mfanyakazi mwenye ufikiaji wa mfumo anahamisha kimyakimya pesa za wateja au kuuza namba zao za simu.", "Mpe kila mtu ufikiaji anaouhitaji tu, hitaji idhini mbili kwa uhamisho wa pesa, weka na kagua kumbukumbu za shughuli, na toa njia salama ya kuripoti tabia ya kutiliwa shaka.")),
"zeroday": (["zero day", "zero-day attack", "software vulnerability attack", "unpatched software attack", "exploit attack", "vulnerability exploit"],
  ("Exploiting software weaknesses (including zero-day attacks)", "Attackers use a flaw in software or a device, sometimes one the maker does not yet know about (a zero-day), to get in without needing you to be tricked. Unpatched devices are the easiest targets.", "An old, never-updated router or website plugin is taken over through a known flaw.", "Turn on automatic updates, replace devices and software that no longer get updates, and reduce what is exposed to the internet."),
  ("Exploitation de failles logicielles (dont attaques zero-day)", "Des attaquants utilisent une faille d'un logiciel ou d'un appareil, parfois inconnue du fabricant (zero-day), pour entrer sans avoir besoin de vous tromper. Les appareils non mis à jour sont les cibles les plus faciles.", "Un vieux routeur ou un plugin de site jamais mis à jour est pris par une faille connue.", "Activez les mises à jour automatiques, remplacez les appareils et logiciels qui ne reçoivent plus de mises à jour et limitez ce qui est exposé à Internet."),
  ("Gukoresha intege nke za porogaramu (harimo zero-day)", "Abagizi ba nabi bakoresha inenge muri porogaramu cyangwa igikoresho, rimwe na rimwe iyo uwayikoze atazi (zero-day), kugira ngo binjire nta mpamvu yo kukuyobya. Ibikoresho bidavuguruwe ni byo byoroshye.", "Router ishaje itigeze ivugururwa cyangwa plugin y'urubuga ifatwa binyuze ku nenge izwi.", "Fungura amavugurura ya otomatike, simbura ibikoresho na porogaramu bitagishyirwaho amavugurura, kandi ugabanye ibyerekanwa kuri interineti."),
  ("Kutumia udhaifu wa programu (ikiwemo zero-day)", "Washambuliaji hutumia kasoro katika programu au kifaa, wakati mwingine ambayo mtengenezaji hajui bado (zero-day), kuingia bila kuhitaji kukudanganya. Vifaa visivyosasishwa ndivyo rahisi zaidi.", "Router ya zamani isiyowahi kusasishwa au programu jalizi ya tovuti inachukuliwa kupitia kasoro inayojulikana.", "Washa masasisho ya kiotomatiki, badilisha vifaa na programu zisizopata masasisho tena, na punguza kinachoonekana mtandaoni.")),
}
